// Small shared helpers: hashing, JSONL persistence, logging, deadlines.
import { createHash } from 'node:crypto';
import { appendFileSync, existsSync, mkdirSync, readFileSync, renameSync, writeFileSync } from 'node:fs';
import { dirname } from 'node:path';

// Inclusive archive cutoff: only captures with timestamp <= this may be used.
export const CUTOFF = '20191231235959';

export const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

export const sha256 = (buf) => createHash('sha256').update(buf).digest('hex');

export function ensureDir(file) {
  const dir = dirname(file);
  if (!existsSync(dir)) mkdirSync(dir, { recursive: true });
}

export function writeJson(file, value) {
  ensureDir(file);
  const tmp = `${file}.tmp`;
  writeFileSync(tmp, `${JSON.stringify(value, null, 2)}\n`);
  renameSync(tmp, file);
}

export function readJson(file, fallback = undefined) {
  try {
    return JSON.parse(readFileSync(file, 'utf8'));
  } catch {
    return fallback;
  }
}

/** Append one JSON object per line; crash-safe enough for resumable progress. */
export function appendJsonl(file, record) {
  ensureDir(file);
  appendFileSync(file, `${JSON.stringify(record)}\n`);
}

export function readJsonl(file) {
  if (!existsSync(file)) return [];
  return readFileSync(file, 'utf8')
    .split('\n')
    .filter((line) => line.trim().length > 0)
    .map((line) => {
      try {
        return JSON.parse(line);
      } catch {
        return null;
      }
    })
    .filter(Boolean);
}

export const log = (...parts) => {
  process.stderr.write(`${new Date().toISOString()} ${parts.join(' ')}\n`);
};

/** True when a 14-digit Wayback timestamp is inside the allowed window. */
export function isPreCutoff(timestamp) {
  return typeof timestamp === 'string' && /^\d{14}$/.test(timestamp) && timestamp <= CUTOFF;
}

export function assertPreCutoff(timestamp, what = 'capture') {
  if (!isPreCutoff(timestamp)) {
    throw new Error(`refusing ${what}: timestamp ${timestamp} is missing, malformed or after cutoff ${CUTOFF}`);
  }
  return timestamp;
}

/** Parse a Wayback-style redirect target, returning its embedded timestamp. */
export function timestampFromRedirect(location) {
  if (!location) return null;
  const m = /(?:web|https?:\/\/web\.archive\.org)\/(\d{14})/i.exec(String(location));
  return m ? m[1] : null;
}

export function isoFromTimestamp(timestamp) {
  if (!isPreCutoff(timestamp)) return null;
  const iso = `${timestamp.slice(0, 4)}-${timestamp.slice(4, 6)}-${timestamp.slice(6, 8)}T${timestamp.slice(8, 10)}:${timestamp.slice(10, 12)}:${timestamp.slice(12, 14)}Z`;
  return iso;
}

// Wayback Machine access: rate-limited HTTP, CDX inventory queries, capture fetches.
//
// Safety rules encoded here:
//   * every capture URL is built from an explicit pre-cutoff timestamp (assertPreCutoff),
//   * redirects are followed manually and a redirect that points at a post-cutoff
//     capture is refused instead of silently fetching it,
//   * `id_` (raw bytes) is preferred, `if_` is the fallback for assets,
//   * timeouts are bounded and failures are classified so the ledger can tell a
//     confirmed archive gap from a timeout / throttle / temporary failure.
import { assertPreCutoff, isPreCutoff, log, sleep, timestampFromRedirect } from './util.mjs';

export const CDX_ENDPOINT = 'https://web.archive.org/cdx/search/cdx';
const USER_AGENT = 'shurik-hazfalafel-recovery/1.0 (+https://github.com/igor-makarov/shurik)';

export const OUTCOME = {
  OK: 'ok',
  ARCHIVE_GAP: 'archive-gap', // CDX answered successfully and listed no captures
  NOT_FOUND: 'not-found', // capture replay answered 404 (page/image never archived)
  TIMEOUT: 'timeout',
  THROTTLED: 'throttled',
  TRANSIENT: 'transient',
  AFTER_CUTOFF: 'after-cutoff', // archive redirect pointed past the cutoff
  BAD_BODY: 'bad-body', // replay returned non-asset bytes (archive error page)
  ERROR: 'error',
};

export class TransientError extends Error {
  constructor(outcome, message, detail = {}) {
    super(message);
    this.outcome = outcome;
    this.detail = detail;
  }
}

/** Minimal token-bucket rate limiter so we stay polite to the archive. */
export class RateLimiter {
  constructor({ minIntervalMs = 400, concurrency = 3 } = {}) {
    this.minIntervalMs = minIntervalMs;
    this.concurrency = concurrency;
    this.active = 0;
    this.nextSlot = 0;
    this.queue = [];
  }

  async acquire() {
    if (this.active >= this.concurrency) {
      await new Promise((resolve) => this.queue.push(resolve));
    }
    this.active += 1;
    const now = Date.now();
    const wait = Math.max(0, this.nextSlot - now);
    this.nextSlot = Math.max(now, this.nextSlot) + this.minIntervalMs;
    if (wait > 0) await sleep(wait);
    let release;
    const gate = new Promise((resolve) => {
      release = resolve;
    });
    const done = async () => {
      this.active -= 1;
      this.queue.shift()?.();
    };
    return async () => {
      await gate;
      await done();
    };
  }
}

export class WaybackClient {
  constructor({ timeoutMs = 60_000, retries = 3, rateLimiter, fetchImpl = fetch } = {}) {
    this.timeoutMs = timeoutMs;
    this.retries = retries;
    this.limiter = rateLimiter ?? new RateLimiter();
    this.fetchImpl = fetchImpl;
    this.stats = { requests: 0, retries: 0, bytes: 0 };
  }

  async rawFetch(url, { method = 'GET', headers = {}, body, redirect = 'manual' } = {}) {
    let lastError;
    for (let attempt = 0; attempt <= this.retries; attempt += 1) {
      const release = await this.limiter.acquire();
      const controller = new AbortController();
      const timer = setTimeout(() => controller.abort(), this.timeoutMs);
      try {
        this.stats.requests += 1;
        const res = await this.fetchImpl(url, {
          method,
          headers: { 'user-agent': USER_AGENT, ...headers },
          body,
          redirect,
          signal: controller.signal,
        });
        if (attempt < this.retries && (res.status === 429 || res.status >= 500)) {
          const backoff = Math.min(30_000, 2_000 * 2 ** attempt);
          log(`retry ${res.status} ${url} in ${backoff}ms`);
          release();
          clearTimeout(timer);
          await sleep(backoff);
          this.stats.retries += 1;
          continue;
        }
        clearTimeout(timer);
        release();
        return res;
      } catch (err) {
        clearTimeout(timer);
        release();
        lastError = err;
        const aborted = err?.name === 'AbortError';
        if (attempt < this.retries) {
          const backoff = Math.min(30_000, 2_000 * 2 ** attempt);
          log(`retry ${aborted ? 'timeout' : err?.message} ${url} in ${backoff}ms`);
          this.stats.retries += 1;
          await sleep(backoff);
          continue;
        }
        throw new TransientError(aborted ? OUTCOME.TIMEOUT : OUTCOME.TRANSIENT, `${aborted ? 'timeout' : 'fetch error'}: ${url}`, {
          cause: String(err?.message ?? err),
        });
      }
    }
    throw lastError;
  }

  /**
   * CDX inventory query. Resolves to { rows, outcome } and never throws for gaps:
   * an empty successful answer is a confirmed archive gap.
   */
  async cdx(query, { limit = 200_000 } = {}) {
    const params = new URLSearchParams({ output: 'json', limit: String(limit), ...query });
    const url = `${CDX_ENDPOINT}?${params}`;
    const res = await this.rawFetch(url);
    if (res.status === 404) return { rows: [], outcome: OUTCOME.ARCHIVE_GAP, url };
    if (res.status !== 200) {
      throw new TransientError(
        res.status === 429 ? OUTCOME.THROTTLED : OUTCOME.TRANSIENT,
        `cdx status ${res.status}`,
        { url, status: res.status },
      );
    }
    const text = await res.text();
    let json;
    try {
      json = JSON.parse(text);
    } catch {
      throw new TransientError(OUTCOME.BAD_BODY, `cdx returned non-JSON body`, { url, snippet: text.slice(0, 200) });
    }
    if (!Array.isArray(json) || json.length === 0) return { rows: [], outcome: OUTCOME.ARCHIVE_GAP, url };
    const [header, ...rest] = json;
    return {
      rows: rest.map((row) => Object.fromEntries(header.map((key, i) => [key, row[i]]))),
      outcome: OUTCOME.OK,
      url,
    };
  }

  /** Captures for one exact URL, all timestamps, deduplicated, pre-cutoff only. */
  async capturesFor(url, { fl = 'timestamp,original,statuscode,mimetype,digest,length' } = {}) {
    const { rows, outcome, url: queryUrl } = await this.cdx({
      url,
      fl,
      to: '20191231235959',
      filter: 'statuscode:200',
    });
    const pre = rows.filter((row) => isPreCutoff(row.timestamp));
    const dropped = rows.length - pre.length;
    return { captures: pre, outcome: dropped > 0 && pre.length === 0 ? OUTCOME.AFTER_CUTOFF : outcome, queryUrl };
  }

  /**
   * Fetch one capture as raw bytes. Refuses post-cutoff replays even when the
   * archive redirects to a newer capture.
   */
  async fetchCapture(timestamp, original, { modifier = 'id_', accept } = {}) {
    assertPreCutoff(timestamp, `capture of ${original}`);
    const target = `https://web.archive.org/web/${timestamp}${modifier}/${original}`;
    let url = target;
    for (let hop = 0; hop < 4; hop += 1) {
      const res = await this.rawFetch(url, { headers: accept ? { accept } : {} });
      if (res.status >= 300 && res.status < 400) {
        const location = res.headers.get('location');
        const ts = timestampFromRedirect(location);
        if (ts && !isPreCutoff(ts)) {
          throw new TransientError(OUTCOME.AFTER_CUTOFF, `redirect to post-cutoff capture ${ts}`, {
            from: url,
            location,
          });
        }
        if (!location) throw new TransientError(OUTCOME.NOT_FOUND, `redirect without location: ${url}`);
        url = location.startsWith('http') ? location : new URL(location, url).toString();
        continue;
      }
      if (res.status === 404) throw new TransientError(OUTCOME.NOT_FOUND, `capture missing: ${target}`, { url });
      if (res.status !== 200) {
        throw new TransientError(res.status === 429 ? OUTCOME.THROTTLED : OUTCOME.TRANSIENT, `replay status ${res.status}`, {
          url,
          status: res.status,
        });
      }
      const buf = Buffer.from(await res.arrayBuffer());
      this.stats.bytes += buf.length;
      return {
        body: buf,
        contentType: res.headers.get('content-type') ?? '',
        requestedTimestamp: timestamp,
        finalUrl: url,
        redirectedTimestamp: timestampFromRedirect(url) ?? timestamp,
      };
    }
    throw new TransientError(OUTCOME.TRANSIENT, `too many redirects for ${target}`);
  }

  /** Text capture with the raw-bytes modifier falling back to `if_`. */
  async fetchTextCapture(timestamp, original) {
    try {
      const res = await this.fetchCapture(timestamp, original, { modifier: 'id_', accept: 'text/html' });
      return res;
    } catch (err) {
      if (err.outcome === OUTCOME.NOT_FOUND) {
        return this.fetchCapture(timestamp, original, { modifier: 'if_', accept: 'text/html' });
      }
      throw err;
    }
  }
}

export { isPreCutoff };

// Tumblr post page parser.
//
// Deliberately dependency-free: the archive returns theme HTML that no modern
// parser survives well, and we only need a handful of well-identified fields.
// Every value we emit comes from the captured HTML; nothing is invented.
import { CUTOFF, isPreCutoff } from './util.mjs';

const NAMED_ENTITIES = {
  amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: '\u00a0', '#39': "'",
  hellip: '…', mdash: '—', ndash: '–', laquo: '«', raquo: '»', ldquo: '“',
  rdquo: '”', lsquo: '‘', rsquo: '’', middot: '·', times: '×', copy: '©', reg: '®',
};

export function decodeEntities(text) {
  if (!text) return '';
  return text.replace(/&(#x?[0-9a-fA-F]+|[a-zA-Z]+);/g, (match, entity) => {
    if (entity[0] === '#') {
      const code = entity[1] === 'x' || entity[1] === 'X' ? parseInt(entity.slice(2), 16) : parseInt(entity.slice(1), 10);
      return Number.isFinite(code) && code > 0 ? String.fromCodePoint(code) : match;
    }
    const named = NAMED_ENTITIES[entity] ?? NAMED_ENTITIES[entity.toLowerCase()];
    return named ?? match;
  });
}

export const stripTags = (html) =>
  decodeEntities(
    String(html ?? '')
      .replace(/<(script|style)[\s\S]*?<\/\1>/gi, ' ')
      .replace(/<br\s*\/?>/gi, '\n')
      .replace(/<\/(p|div|li|h[1-6])>/gi, '\n')
      .replace(/<[^>]+>/g, ''),
  )
    .replace(/[ \t\u00a0]+/g, ' ')
    .replace(/\n\s*\n\s*/g, '\n')
    .trim();

/** Return [start, end) of the element whose opening tag begins at `openIdx`. */
export function elementRange(html, openIdx, tagName = 'div') {
  const openRe = new RegExp(`<${tagName}\\b[^>]*>`, 'gi');
  openRe.lastIndex = openIdx;
  const openMatch = openRe.exec(html);
  if (!openMatch || openMatch.index !== openIdx) return null;
  let depth = 0;
  const scanner = new RegExp(`<(/?)${tagName}\\b[^>]*>`, 'gi');
  scanner.lastIndex = openIdx;
  let m;
  while ((m = scanner.exec(html))) {
    depth += m[1] === '/' ? -1 : 1;
    if (depth === 0) return [openIdx, m.index + m[0].length];
  }
  return null;
}

function attribute(tag, name) {
  const re = new RegExp(`\\b${name}\\s*=\\s*("([^"]*)"|'([^']*)'|([^\\s>]+))`, 'i');
  const m = re.exec(tag);
  if (!m) return null;
  return decodeEntities(m[2] ?? m[3] ?? m[4] ?? '');
}

/** Class list of an opening tag. */
const classesOf = (tag) => (attribute(tag, 'class') ?? '').split(/\s+/).filter(Boolean);

export function metaContent(html, property) {
  const re = new RegExp(`<meta[^>]+(?:property|name)=["']${property}["'][^>]*>`, 'gi');
  for (const tag of html.match(re) ?? []) {
    const content = attribute(tag, 'content');
    if (content) return content;
  }
  return null;
}

/** Non-image post media (video/audio/quote/photoset markers) kept as evidence. */
const EMBED_RE = /<(video|audio|source|iframe|embed)\b([^>]*)>/gi;
const EMBED_HREF_RE = /\b(?:src|data-orig-file|data-href|href)=["']([^"']+)["']/gi;

function embeddedMedia(html) {
  const out = [];
  for (const m of html.matchAll(EMBED_RE)) {
    const tag = m[0];
    const src = attribute(tag, 'src') ?? attribute(tag, 'data-href');
    out.push({ kind: m[1].toLowerCase(), url: src ?? null });
  }
  for (const m of html.matchAll(/data-(?:tumblr-)?(?:video|audio|post)-id=["'](\d+)["']/gi)) {
    out.push({ kind: 'tumblr-media-id', id: m[1] });
  }
  return out;
}

const AVATAR_RE = /\/avatar_|\/preload\/|\/tumblr_.*_avatar/i;
const TRACKER_RE = /stats\.|pixel|1x1|tracking|beacon|doubleclick|analytics/i;

/**
 * Images that belong to a post body. Avatars, theme assets and tracking pixels
 * are excluded; everything else is kept with its alt/caption text.
 */
export function postImages(postHtml, pageHtml = postHtml) {
  const scope = postHtml ?? pageHtml;
  const seen = new Set();
  const images = [];
  for (const m of scope.matchAll(/<img\b[^>]*>/gi)) {
    const tag = m[0];
    const src = attribute(tag, 'src') ?? attribute(tag, 'data-src');
    if (!src) continue;
    if (!/^https?:/i.test(src)) continue;
    if (AVATAR_RE.test(src) || TRACKER_RE.test(src)) continue;
    if (!/media\.tumblr\.com|\/tumblr_|\/image\//i.test(src)) continue;
    const key = src.replace(/^https?:/, '');
    if (seen.has(key)) continue;
    seen.add(key);
    images.push({
      url: src,
      alt: attribute(tag, 'alt') ?? '',
      width: attribute(tag, 'width') ?? null,
      height: attribute(tag, 'height') ?? null,
    });
  }
  // <a href> wrappers sometimes carry the full-size original for the same photo.
  for (const m of scope.matchAll(/<a\b[^>]*href=["']([^"']*media\.tumblr\.com[^"']*)["'][^>]*>/gi)) {
    const src = decodeEntities(m[1]);
    const key = src.replace(/^https?:/, '');
    if (seen.has(key) || AVATAR_RE.test(src) || TRACKER_RE.test(src)) continue;
    seen.add(key);
    images.push({ url: src, alt: '', width: null, height: null });
  }
  return images;
}

/** Split a Tumblr media URL into its variant coordinates. */
export function mediaKey(url) {
  const u = String(url);
  const m = /^(https?:\/\/)([^/]+)\/([0-9a-f]{6,40})\/(tumblr_[A-Za-z0-9]+?)(?:_(\d+))?(\.[A-Za-z0-9]+)$/i.exec(u);
  if (!m) return null;
  return { host: m[2], dir: m[3], slug: m[4], size: m[5] ?? null, ext: m[6] };
}

/**
 * Parse a captured Tumblr post page. Returns null when the capture is not a post
 * page (login walls, error pages, blog indexes).
 */
export function parsePostPage(html, { url, timestamp, rawStatus } = {}) {
  if (!html || typeof html !== 'string') return null;
  const isErrorPage = /<title>\s*(?:Internet Archive|404|Wayback Machine has not archived)/i.test(html);
  const postId =
    (/[?&]post(?:ID)?=([0-9]{6,})/i.exec(html)?.[1]) ??
    /post\/([0-9]{6,})/.exec(url ?? '')?.[1] ??
    null;
  if (!postId) return null;
  if (isErrorPage && !/<div class="post"/i.test(html)) {
    return { postId, parseError: 'error-page', url, timestamp, rawStatus };
  }

  const postStart = html.search(/<div[^>]*class=["'][^"']*\bpost\b[^"']*["'][^>]*>/i);
  let postHtml = html;
  let postHtmlRange = null;
  if (postStart >= 0) {
    const range = elementRange(html, postStart, 'div');
    if (range) {
      postHtml = html.slice(range[0], range[1]);
      postHtmlRange = range;
    }
  }

  const captionBlocks = [];
  for (const m of postHtml.matchAll(/<div[^>]*class=["'][^"']*\b(?:copy|caption|post-content|post_text|caption-inner)\b[^"']*["'][^>]*>/gi)) {
    const range = elementRange(postHtml, m.index, 'div');
    if (range) {
      const inner = postHtml.slice(range[0], range[1]);
      const innerInner = inner.replace(/^<div[^>]*>/i, '').replace(/<\/div>$/i, '');
      captionBlocks.push(innerInner.trim());
    }
  }
  const ogDescription = metaContent(html, 'og:description') ?? metaContent(html, 'twitter:description');
  const captionHtml = captionBlocks.length > 0 ? captionBlocks.join('\n') : (ogDescription ?? '');

  const tags = [];
  const seenTags = new Set();
  for (const m of html.matchAll(/<a\b[^>]*href=["']([^"']*\/tagged\/([^"'#?]+))[^"']*["'][^>]*>/gi)) {
    const raw = decodeEntities(m[2]);
    const label = stripTags(m[0]) || raw;
    const key = raw.toLowerCase();
    if (seenTags.has(key)) continue;
    seenTags.add(key);
    tags.push({ slug: raw, name: label || raw, url: m[1] });
  }

  const postedOn = /title=["']Posted on ([^"']+)["']/i.exec(html)?.[1] ?? null;
  const permalink =
    metaContent(html, 'og:url') ??
    attribute(/<link[^>]+rel=["']canonical["'][^>]*>/i.exec(html)?.[0] ?? '', 'href') ??
    (/post\/([0-9]{6,})/.exec(url ?? '') ? `http://hazfalafel.com/post/${postId}` : null);

  const images = postImages(postHtml, html);
  const embedded = embeddedMedia(postHtml);
  const ogType = metaContent(html, 'og:type');

  return {
    postId,
    permalink,
    parsedUrl: url,
    captureTimestamp: timestamp,
    captureWithinCutoff: isPreCutoff(timestamp) && timestamp <= CUTOFF,
    title: metaContent(html, 'og:title'),
    blogName: /blogName=([A-Za-z0-9_-]+)/i.exec(html)?.[1] ?? null,
    postedOn,
    ogType,
    keywords: metaContent(html, 'keywords'),
    captionHtml,
    captionText: stripTags(captionHtml),
    description: ogDescription,
    tags,
    images,
    embedded,
    postHtmlRange,
    postHtmlLength: postHtml.length,
    parseError: null,
  };
}

// Image recovery helpers: archived-CDN variants, body validation, capture choice.
import { OUTCOME } from './wayback.mjs';
import { mediaKey } from './parse-post.mjs';

/** Magic-byte sniffing: archived HTML error pages must never be stored as images. */
export function detectImageType(buf) {
  if (!Buffer.isBuffer(buf) || buf.length < 12) return null;
  if (buf[0] === 0xff && buf[1] === 0xd8 && buf[2] === 0xff) return { mimetype: 'image/jpeg', ext: 'jpg' };
  if (buf.subarray(0, 8).equals(Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]))) {
    return { mimetype: 'image/png', ext: 'png' };
  }
  if (buf.subarray(0, 4).toString('ascii') === 'GIF8') return { mimetype: 'image/gif', ext: 'gif' };
  if (buf.subarray(0, 4).toString('ascii') === 'RIFF' && buf.subarray(8, 12).toString('ascii') === 'WEBP') {
    return { mimetype: 'image/webp', ext: 'webp' };
  }
  if (buf.subarray(0, 2).toString('ascii') === 'BM') return { mimetype: 'image/bmp', ext: 'bmp' };
  if ((buf[0] === 0x49 && buf[1] === 0x49) || (buf[0] === 0x4d && buf[1] === 0x4d)) {
    return { mimetype: 'image/tiff', ext: 'tif' };
  }
  return null;
}

/** Reject archive error/interstitial pages masquerading as image bytes. */
export function looksLikeHtml(buf) {
  const head = buf.subarray(0, 512).toString('utf8').trimStart().toLowerCase();
  return head.startsWith('<!doctype html') || head.startsWith('<html') || head.startsWith('<?xml') || head.includes('<head');
}

export function validateImageBody(buf, contentType = '') {
  if (/text\/html/i.test(contentType)) return { ok: false, reason: 'html-content-type' };
  if (looksLikeHtml(buf)) return { ok: false, reason: 'html-body' };
  const type = detectImageType(buf);
  if (!type) return { ok: false, reason: 'unknown-magic-bytes' };
  return { ok: true, ...type, bytes: buf.length };
}

/** Ordered size variants of a Tumblr media URL (bigger first, original last). */
const SIZE_VARIANTS = ['1280', '1024', '540', '500', '400', '250', '128', '64'];

/** Alternate cache shards; captures sometimes exist under a different host. */
const SHARD_VARIANTS = ['24', '2', '8', '16', '32', '1', '64'];

export function variantUrls(url) {
  const key = mediaKey(url);
  if (!key) return [url];
  const build = (host, size) => {
    const sizePart = size ? `_${size}` : '';
    return `http://${host}.media.tumblr.com/${key.dir}/${key.slug}${sizePart}${key.ext}`;
  };
  const urls = [];
  const sizes = key.size ? [...SIZE_VARIANTS.filter((s) => s !== key.size), null] : [null];
  urls.push(build(key.host, key.size)); // exact original first
  for (const size of sizes) {
    const candidate = build(key.host, size);
    if (!urls.includes(candidate)) urls.push(candidate);
  }
  for (const shard of SHARD_VARIANTS) {
    if (shard === key.host) continue;
    for (const size of [key.size, '1280', null]) {
      const candidate = build(shard, size);
      if (!urls.includes(candidate)) urls.push(candidate);
    }
  }
  return urls;
}

/** Distinct archived-capture lookup strategies, tried in order, for one image. */
export function imageStrategies(url, { hostPrefix = true } = {}) {
  const key = mediaKey(url);
  const strategies = [
    { method: 'cdx-exact-capture', url },
  ];
  if (key && hostPrefix) {
    strategies.push({ method: 'cdx-host-prefix-sizes', url: `http://${key.host}.media.tumblr.com/${key.dir}/${key.slug}` });
  }
  for (const variant of variantUrls(url).slice(1, 12)) {
    strategies.push({ method: 'cdx-variant-url', url: variant });
  }
  return strategies;
}

/** Choose the capture to replay: closest to the post capture, still pre-cutoff. */
export function chooseCapture(captures, nearTimestamp) {
  if (!captures.length) return null;
  const sorted = [...captures].sort((a, b) => Math.abs(Number(a.timestamp) - Number(nearTimestamp ?? 0)) - Math.abs(Number(b.timestamp) - Number(nearTimestamp ?? 0)));
  return sorted[0];
}

export { OUTCOME };

// Minimal OCI artifact builder + GHCR registry client (no dependencies).
//
// Each Tumblr post becomes one OCI image artifact:
//   config  -> full post metadata (HTML/text/tags/captions/provenance) in Labels
//   layers  -> one tar layer per recovered image, each holding the image bytes
//              plus a UTF-8 `.caption.txt` sidecar (Hebrew preserved).
import { createHash } from 'node:crypto';
import { sha256 } from './util.mjs';

const BLOCK = 512;

function tarHeader({ name, size, type = '0' }) {
  const header = Buffer.alloc(BLOCK);
  const write = (value, offset, length) => {
    header.write(value.slice(0, length - 1), offset, length - 1, 'utf8');
  };
  write(name, 0, 100);
  write('000644\0', 100, 8);
  write('000000\0', 108, 8);
  write('000000\0', 116, 8);
  write(`${size.toString(8).padStart(11, '0')}\0`, 124, 12);
  write('00000000000\0', 136, 12); // deterministic mtime
  header.write('        ', 148, 8, 'utf8'); // checksum placeholder
  header.write(type, 156, 1, 'utf8');
  header.write('ustar\0', 257, 6, 'utf8');
  header.write('00', 263, 2, 'utf8');
  let sum = 0;
  for (const byte of header) sum += byte;
  header.write(`${sum.toString(8).padStart(6, '0')}\0 `, 148, 8, 'utf8');
  return header;
}

/** Deterministic (reproducible) ustar tar archive. */
export function makeTar(entries) {
  const chunks = [];
  for (const entry of entries) {
    const data = Buffer.isBuffer(entry.data) ? entry.data : Buffer.from(entry.data ?? '', 'utf8');
    if (data.length > 8 * 1024 * 1024) throw new Error(`tar entry too large: ${entry.name}`);
    chunks.push(tarHeader({ name: entry.name, size: data.length }));
    chunks.push(data);
    const pad = (BLOCK - (data.length % BLOCK)) % BLOCK;
    if (pad > 0) chunks.push(Buffer.alloc(pad));
  }
  chunks.push(Buffer.alloc(BLOCK * 2));
  return Buffer.concat(chunks);
}

const jsonBlob = (value) => Buffer.from(`${JSON.stringify(value, null, 2)}\n`, 'utf8');

export const MEDIA_TYPES = {
  manifest: 'application/vnd.oci.image.manifest.v1+json',
  config: 'application/vnd.oci.image.config.v1+json',
  layer: 'application/vnd.oci.image.layer.v1.tar',
};

const SOURCE_URL = 'https://github.com/igor-makarov/shurik';

/**
 * Build the artifact for one post.
 * `post` is the parsed/recovered record; `images` are validated recovered files.
 */
export function buildArtifact({ post, images, createdAt, generator = 'shurik-hazfalafel-recovery' }) {
  const metadata = {
    schema: 'shurik.hazfalafel/post/v1',
    postId: post.postId,
    site: 'hazfalafel.com',
    blog: post.blogName ?? 'icanhazfalafel',
    permalink: post.permalink,
    originalUrl: post.permalink,
    capture: {
      timestamp: post.captureTimestamp,
      url: post.captureUrl ?? null,
      modifiedTimestamp: post.captureModifiedTimestamp ?? null,
      redirectedTimestamp: post.captureRedirectedTimestamp ?? null,
      waybackId: post.captureUrl ?? null,
      withinCutoff: post.captureTimestamp <= '20191231235959',
    },
    allCaptures: post.captures ?? [],
    postedOn: post.postedOn ?? null,
    title: post.title ?? null,
    tags: (post.tags ?? []).map((tag) => ({ name: tag.name, slug: tag.slug })),
    caption: {
      html: post.captionHtml ?? '',
      text: post.captionText ?? '',
      perImage: images.map((img) => ({ path: img.layerPath, caption: img.caption ?? null, alt: img.alt ?? null })),
    },
    content: {
      html: post.captionHtml ?? '',
      text: post.captionText ?? '',
      postBodyHtml: post.postHtml ?? null,
      description: post.description ?? null,
    },
    embeddedMedia: post.embedded ?? [],
    images: images.map((img) => ({
      path: img.layerPath,
      originalUrl: img.originalUrl,
      captureTimestamp: img.captureTimestamp,
      captureUrl: img.captureUrl,
      strategy: img.strategy ?? null,
      sha256: sha256(img.data),
      bytes: img.data.length,
      mimetype: img.mimetype,
      caption: img.caption ?? null,
      alt: img.alt ?? null,
      missing: false,
    })),
    missingImages: post.missingImages ?? [],
    recovery: {
      generator,
      cutoff: '20191231235959',
      recoveredAt: createdAt,
      methods: post.methods ?? [],
      notes: post.notes ?? null,
      partial: images.length < (post.expectedImages ?? images.length),
    },
    source: SOURCE_URL,
  };

  const config = {
    architecture: 'amd64',
    os: 'linux',
    created: createdAt,
    config: {
      Env: [],
      Labels: {
        'org.opencontainers.image.title': `hazfalafel post ${post.postId}`,
        'org.opencontainers.image.description': (post.captionText ?? '').slice(0, 400) || `hazfalafel post ${post.postId}`,
        'org.opencontainers.image.source': SOURCE_URL,
        'org.opencontainers.image.url': post.permalink ?? `http://hazfalafel.com/post/${post.postId}`,
        'org.opencontainers.image.created': createdAt,
        'org.opencontainers.image.version': post.captureTimestamp ?? '',
        'org.opencontainers.image.revision': post.postId,
        'io.hazfalafel.post.id': String(post.postId),
        'io.hazfalafel.post.permalink': post.permalink ?? '',
        'io.hazfalafel.post.tags': metadata.tags.map((t) => t.name).join(','),
        'io.hazfalafel.post.caption.text': post.captionText ?? '',
        'io.hazfalafel.post.content.html': post.captionHtml ?? '',
        'io.hazfalafel.post.capture.timestamp': post.captureTimestamp ?? '',
        'io.hazfalafel.post.capture.url': post.captureUrl ?? '',
        'io.hazfalafel.post.image.count': String(images.length),
        'io.hazfalafel.post.image.missing': String((post.missingImages ?? []).length),
        'io.hazfalafel.post.metadata.json': JSON.stringify(metadata),
      },
    },
    history: [{ created: createdAt, created_by: `${generator} post ${post.postId}` }],
    rootfs: { type: 'layers', diff_ids: [] },
  };

  const layers = [];
  for (const image of images) {
    const captionText = [image.caption ?? '', image.alt ?? ''].filter(Boolean).join('\n');
    const tar = makeTar([
      { name: image.layerPath, data: image.data },
      { name: `${image.layerPath}.caption.txt`, data: `${captionText}\n`, type: '0' },
    ]);
    const digest = `sha256:${sha256(tar)}`;
    config.rootfs.diff_ids.push(digest);
    layers.push({
      mediaType: MEDIA_TYPES.layer,
      digest,
      size: tar.length,
      annotations: {
        'org.opencontainers.image.title': image.layerPath,
        'io.hazfalafel.image.original.url': image.originalUrl,
        'io.hazfalafel.image.capture.timestamp': image.captureTimestamp ?? '',
        'io.hazfalafel.image.capture.url': image.captureUrl ?? '',
        'io.hazfalafel.image.caption': captionText,
        'io.hazfalafel.image.sha256': sha256(image.data),
        'io.hazfalafel.image.recovery.strategy': image.strategy ?? '',
      },
    });
  }

  const configBlob = jsonBlob(config);
  const manifest = {
    schemaVersion: 2,
    mediaType: MEDIA_TYPES.manifest,
    config: { mediaType: MEDIA_TYPES.config, digest: `sha256:${sha256(configBlob)}`, size: configBlob.length },
    layers,
    annotations: {
      'org.opencontainers.image.title': `hazfalafel post ${post.postId}`,
      'org.opencontainers.image.description': (post.captionText ?? '').slice(0, 400) || `hazfalafel post ${post.postId}`,
      'org.opencontainers.image.source': SOURCE_URL,
      'org.opencontainers.image.url': post.permalink ?? `http://hazfalafel.com/post/${post.postId}`,
      'org.opencontainers.image.created': createdAt,
      'org.opencontainers.image.licenses': 'see-source',
      'io.hazfalafel.post.id': String(post.postId),
      'io.hazfalafel.post.capture.timestamp': post.captureTimestamp ?? '',
      'io.hazfalafel.post.partial': String(images.length < (post.expectedImages ?? images.length)),
      'io.shurik.recovery.schema': 'shurik.hazfalafel/post/v1',
    },
  };

  return { manifest, manifestBytes: jsonBlob(manifest), configBytes: configBlob, metadata };
}

export class RegistryError extends Error {
  constructor(status, body, url) {
    super(`registry ${status} for ${url}: ${String(body).slice(0, 300)}`);
    this.status = status;
    this.body = String(body).slice(0, 1000);
    this.url = url;
  }
}

export class GhcrRegistry {
  constructor({ registry = 'ghcr.io', repository, username, token, fetchImpl = fetch } = {}) {
    if (!repository) throw new Error('repository required');
    this.registry = registry;
    this.repository = repository;
    this.username = username;
    this.token = token;
    this.fetchImpl = fetchImpl;
    this.accessToken = null;
    this.accessTokenExpiresAt = 0;
    this.stats = { blobUploads: 0, blobsSkipped: 0, manifests: 0 };
  }

  async access() {
    if (this.accessToken && Date.now() < this.accessTokenExpiresAt - 30_000) return this.accessToken;
    if (!this.username || !this.token) throw new Error('registry credentials missing from environment');
    const scope = `repository:${this.repository}:pull,push`;
    const url = `https://${this.registry}/token?service=${this.registry}&scope=${encodeURIComponent(scope)}`;
    const res = await this.fetchImpl(url, {
      headers: { authorization: `Basic ${Buffer.from(`${this.username}:${this.token}`).toString('base64')}` },
    });
    if (!res.ok) throw new RegistryError(res.status, await res.text(), url);
    const body = await res.json();
    this.accessToken = body.token;
    this.accessTokenExpiresAt = Date.now() + (Number(body.expires_in ?? 300) - 60) * 1000;
    return this.accessToken;
  }

  async request(path, init = {}) {
    const token = await this.access();
    const url = `https://${this.registry}${path}`;
    const res = await this.fetchImpl(url, {
      ...init,
      headers: {
        authorization: `Bearer ${token}`,
        accept: 'application/vnd.oci.image.manifest.v1+json, application/vnd.oci.image.index.v1+json, application/vnd.docker.distribution.manifest.v2+json',
        ...(init.headers ?? {}),
      },
    });
    if (!res.ok && res.status !== 404) throw new RegistryError(res.status, await res.text(), url);
    return res;
  }

  async blobExists(digest) {
    const res = await this.request(`/v2/${this.repository}/blobs/${digest}`, { method: 'HEAD' });
    return res.status === 200;
  }

  async pushBlob(buf) {
    const digest = `sha256:${sha256(buf)}`;
    if (await this.blobExists(digest)) {
      this.stats.blobsSkipped += 1;
      return digest;
    }
    const start = await this.request(`/v2/${this.repository}/blobs/uploads/`, { method: 'POST' });
    const location = start.headers.get('location');
    if (!location) throw new Error('registry did not return an upload location');
    const putUrl = `${location.startsWith('http') ? '' : `https://${this.registry}`}${location}${location.includes('?') ? '&' : '?'}digest=${encodeURIComponent(digest)}`;
    const res = await this.request(putUrl.startsWith('http') ? putUrl.slice(`https://${this.registry}`.length) : putUrl, {
      method: 'PUT',
      headers: { 'content-type': 'application/octet-stream' },
      body: buf,
    });
    if (!res.ok) throw new RegistryError(res.status, await res.text(), putUrl);
    this.stats.blobUploads += 1;
    return digest;
  }

  async pushManifest(tag, manifest, mediaType = MEDIA_TYPES.manifest) {
    const bytes = Buffer.isBuffer(manifest) ? manifest : Buffer.from(JSON.stringify(manifest), 'utf8');
    const res = await this.request(`/v2/${this.repository}/manifests/${tag}`, {
      method: 'PUT',
      headers: { 'content-type': mediaType },
      body: bytes,
    });
    if (!res.ok) throw new RegistryError(res.status, await res.text(), `manifest ${tag}`);
    this.stats.manifests += 1;
    return { digest: res.headers.get('docker-content-digest'), bytes };
  }

  async pullManifest(tag) {
    const res = await this.request(`/v2/${this.repository}/manifests/${tag}`);
    if (res.status === 404) return null;
    return res.json();
  }
}

export { sha256, createHash, SOURCE_URL };

// Resumable recovery pipeline. Every stage appends JSONL to recovery/data so an
// interrupted run can resume without re-downloading what it already has.
import { appendFileSync, existsSync, mkdirSync, readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { parsePostPage, stripTags } from './lib/parse-post.mjs';
import { chooseCapture, imageStrategies, validateImageBody } from './lib/images.mjs';
import { OUTCOME, WaybackClient } from './lib/wayback.mjs';
import { CUTOFF, appendJsonl, assertPreCutoff, isoFromTimestamp, log, readJsonl, sha256 } from './lib/util.mjs';

const HERE = dirname(fileURLToPath(import.meta.url));
export const ROOT = join(HERE, '..');
export const DATA = join(ROOT, 'data');
export const CACHE = join(ROOT, '.cache');

export const PATHS = {
  postCaptures: join(DATA, 'post-captures.jsonl'),
  siteUrls: join(DATA, 'site-urls.jsonl'),
  posts: join(DATA, 'posts.jsonl'),
  images: join(DATA, 'images.jsonl'),
  missing: join(DATA, 'missing.jsonl'),
  published: join(DATA, 'published.jsonl'),
  methods: join(DATA, 'methods.jsonl'),
};

export const mkdirs = () => {
  for (const dir of [DATA, join(CACHE, 'posts'), join(CACHE, 'images')]) if (!existsSync(dir)) mkdirSync(dir, { recursive: true });
};

/** Richness comparison: reruns must never replace better metadata with worse. */
export function postScore(post) {
  return (
    (post.images?.length ?? 0) * 1000 +
    (post.captionHtml?.length ?? 0) +
    (post.tags?.length ?? 0) * 50 +
    (post.captureUrl ? 20 : 0) +
    (post.postedOn ? 5 : 0)
  );
}

export function mergePost(oldPost, newPost) {
  if (!oldPost) return newPost;
  const keep = postScore(oldPost) >= postScore(newPost) ? oldPost : newPost;
  const other = keep === oldPost ? newPost : oldPost;
  return {
    ...other,
    ...keep,
    images: dedupeImages([...(keep.images ?? []), ...(other.images ?? [])]),
    tags: dedupeBy([...(keep.tags ?? []), ...(other.tags ?? [])], (tag) => String(tag.slug ?? tag).toLowerCase()),
    captures: dedupeBy([...(keep.captures ?? []), ...(other.captures ?? [])], (ts) => ts).sort(),
    // Keep the earliest confirmed capture as provenance and remember alternates.
    captureTimestamp: [keep.captureTimestamp, other.captureTimestamp].filter(Boolean).sort()[0] ?? null,
    mergedFrom: dedupeBy([...(keep.mergedFrom ?? []), ...(other.mergedFrom ?? [])], (v) => v).sort(),
  };
}

export const dedupeBy = (items, keyFn) => {
  const seen = new Set();
  const out = [];
  for (const item of items) {
    const key = keyFn(item);
    if (key == null || seen.has(key)) continue;
    seen.add(key);
    out.push(item);
  }
  return out;
};

export function dedupeImages(images) {
  const byUrl = new Map();
  for (const image of images) {
    if (!image?.url) continue;
    const existing = byUrl.get(image.url);
    if (!existing || (image.resolved && !existing.resolved)) byUrl.set(image.url, { ...existing, ...image });
  }
  return [...byUrl.values()];
}

/** Load a JSONL file as a keyed map for resumable stages. */
export function loadKeyed(file, keyFn) {
  const map = new Map();
  for (const record of readJsonl(file)) {
    const key = keyFn(record);
    if (key != null) map.set(key, map.has(key) ? mergeRecord(map.get(key), record) : record);
  }
  return map;
}

function mergeRecord(oldRec, newRec) {
  return { ...oldRec, ...newRec, attempts: [...(oldRec.attempts ?? []), ...(newRec.attempts ?? [])] };
}

export class Recovery {
  constructor({ concurrency = 4, cdxConcurrency = 2, cache = CACHE, dryRun = false } = {}) {
    mkdirs();
    this.client = new WaybackClient({ timeoutMs: 60_000 });
    this.cdxLimiter = cdxConcurrency;
    this.concurrency = concurrency;
    this.cache = cache;
    this.dryRun = dryRun;
    this.posts = loadKeyed(PATHS.posts, (r) => r.postId);
    this.images = loadKeyed(PATHS.images, (r) => `${r.postId}|${r.originalUrl}`);
  }

  logMethod(entry) {
    appendJsonl(PATHS.methods, { at: new Date().toISOString(), ...entry });
  }

  noteMissing(entry) {
    appendJsonl(PATHS.missing, { at: new Date().toISOString(), ...entry });
  }

  /**
   * Stage 1 — inventory captured URLs. Cheap CDX queries, resumable by urlkey.
   */
  async discover({ limit = 0 } = {}) {
    const known = new Set(readJsonl(PATHS.postCaptures).map((r) => `${r.urlkey ?? r.original}|${r.timestamp}`));
    const queries = [
      { name: 'post-pages', query: { url: 'hazfalafel.com/post/*', collapse: 'urlkey', filter: 'statuscode:200', fl: 'urlkey,timestamp,original,statuscode,mimetype,digest,length' } },
      { name: 'amp-pages', query: { url: 'hazfalafel.com/post/*/amp', collapse: 'urlkey', filter: 'statuscode:200', fl: 'urlkey,timestamp,original,statuscode,mimetype,digest,length' } },
      { name: 'photoset-pages', query: { url: 'hazfalafel.com/post/*/photoset_iframe/*', collapse: 'urlkey', filter: 'statuscode:200', fl: 'urlkey,timestamp,original,statuscode,mimetype,digest,length' } },
      { name: 'tag-pages', query: { url: 'hazfalafel.com/tagged/*', collapse: 'urlkey', filter: 'statuscode:200', fl: 'urlkey,timestamp,original,statuscode,mimetype,digest,length' } },
    ];
    let added = 0;
    for (const { name, query } of queries) {
      if (limit && added >= limit) break;
      const res = await this.client.cdx({ ...query, to: CUTOFF });
      this.logMethod({ stage: 'discover', query: name, outcome: res.outcome, rows: res.rows.length, url: res.url });
      log(`discover ${name}: ${res.rows.length} rows (${res.outcome})`);
      for (const row of res.rows) {
        if (!/^\d{14}$/.test(row.timestamp ?? '')) continue;
        if (row.timestamp > CUTOFF) continue;
        const key = `${row.urlkey ?? row.original}|${row.timestamp}`;
        if (known.has(key)) continue;
        known.add(key);
        appendJsonl(PATHS.postCaptures, { source: name, ...row });
        added += 1;
      }
    }
    return { added };
  }

  /** Post ids seen anywhere in the CDX inventory (permalink, amp, photoset). */
  inventoryPostIds() {
    const ids = new Map();
    for (const row of readJsonl(PATHS.postCaptures)) {
      const m = /\/post\/(\d{6,})/.exec(row.original ?? '');
      if (!m) continue;
      const list = ids.get(m[1]) ?? [];
      if (!list.some((r) => r.timestamp === row.timestamp && r.original === row.original)) {
        list.push({ timestamp: row.timestamp, original: row.original, source: row.source, mimetype: row.mimetype, digest: row.digest, statuscode: row.statuscode });
      }
      ids.set(m[1], list);
    }
    return ids;
  }

  cachePath(ts, original) {
    const name = sha256(`${ts}|${original}`).slice(0, 24);
    return join(this.cache, 'posts', `${ts}-${name}.html`);
  }

  /** Stage 2 — fetch + parse captured post pages. */
  async crawlPosts({ postIds = null, perPostCaptures = 2 } = {}) {
    const inventory = this.inventoryPostIds();
    const targets = postIds ?? [...inventory.keys()].sort();
    const queue = [];
    for (const postId of targets) {
      const captures = (inventory.get(postId) ?? []).filter((c) => c.timestamp <= CUTOFF).sort((a, b) => a.timestamp.localeCompare(b.timestamp));
      for (const capture of captures.slice(0, perPostCaptures)) queue.push({ postId, ...capture });
    }
    const done = new Set();
    for (const post of this.posts.values()) for (const ts of post.captures ?? []) done.add(`${post.postId}|${ts}`);
    const pending = queue.filter((item) => !done.has(`${item.postId}|${item.timestamp}`));
    log(`crawlPosts: ${pending.length} capture fetches pending (${this.posts.size} posts known)`);
    let index = 0;
    const worker = async () => {
      while (index < pending.length) {
        const item = pending[index++];
        await this.ingestCapture(item);
      }
    };
    await Promise.all(Array.from({ length: this.concurrency }, worker));
    return { posts: this.posts.size };
  }

  async ingestCapture({ postId, timestamp, original, source }) {
    const attempts = [];
    try {
      assertPreCutoff(timestamp, `post ${postId} capture`);
      const file = this.cachePath(timestamp, original);
      let html;
      if (existsSync(file)) {
        html = readFileSync(file, 'utf8');
      } else {
        const res = await this.client.fetchTextCapture(timestamp, original);
        html = res.body.toString('utf8');
        mkdirSync(dirname(file), { recursive: true });
        appendFileSync(file, html);
        attempts.push({ method: 'replay-id_', url: res.finalUrl, outcome: OUTCOME.OK, bytes: res.body.length });
      }
      const parsed = parsePostPage(html, { url: original, timestamp });
      if (!parsed) {
        attempts.push({ method: 'parse', url: original, outcome: 'not-a-post-page' });
        this.noteMissing({ kind: 'post', postId, url: original, captureTimestamp: timestamp, source, attempts, outcome: 'not-a-post-page' });
        this.mergePostRecord({ postId, captures: [timestamp], captureTimestamp: timestamp, permalink: `http://hazfalafel.com/post/${postId}`, images: [], tags: [], captionHtml: '', captionText: '', expectedImages: 0, parseNote: 'not-a-post-page' });
        return;
      }
      const captureUrl = `https://web.archive.org/web/${timestamp}id_/${original}`;
      this.mergePostRecord({
        ...parsed,
        postId,
        expectedImages: parsed.images.length,
        captureUrl,
        captureOriginalUrl: original,
        captureModifiedTimestamp: timestamp,
        captureRedirectedTimestamp: timestamp,
        captureSource: source ?? 'post-pages',
        captures: [timestamp],
        postHtml: extractPostHtml(html, parsed),
      });
      this.logMethod({ stage: 'crawl-posts', postId, captureTimestamp: timestamp, url: captureUrl, outcome: OUTCOME.OK, images: parsed.images.length, bytes: html.length, attempts });
    } catch (err) {
      const outcome = err.outcome ?? OUTCOME.ERROR;
      attempts.push({ method: 'replay', url: original, outcome, error: String(err.message).slice(0, 300) });
      this.noteMissing({ kind: 'post', postId, url: original, captureTimestamp: timestamp, source, outcome, attempts, error: String(err.message).slice(0, 400) });
      this.logMethod({ stage: 'crawl-posts', postId, captureTimestamp: timestamp, url: original, outcome, attempts });
    }
  }

  mergePostRecord(record) {
    const merged = mergePost(this.posts.get(record.postId), record);
    this.posts.set(record.postId, merged);
    appendJsonl(PATHS.posts, merged);
    return merged;
  }

  /** Stage 3 — resolve every post image to archived bytes, cache, and ledger. */
  async crawlImages({ postIds = null, maxPerPost = 12 } = {}) {
    const targets = (postIds ?? [...this.posts.keys()]).filter((id) => (this.posts.get(id)?.images?.length ?? 0) > 0);
    const pendingImages = [];
    for (const postId of targets) {
      const post = this.posts.get(postId);
      for (const image of post.images.slice(0, maxPerPost)) {
        const key = `${postId}|${image.url}`;
        if (this.images.has(key) && this.images.get(key).resolved) continue;
        pendingImages.push({ postId, image, near: post.captureTimestamp });
      }
    }
    log(`crawlImages: ${pendingImages.length} image lookups pending`);
    let index = 0;
    const worker = async () => {
      while (index < pendingImages.length) {
        const item = pendingImages[index++];
        await this.ingestImage(item);
      }
    };
    await Promise.all(Array.from({ length: this.concurrency }, worker));
    return { resolved: [...this.images.values()].filter((i) => i.resolved).length };
  }

  async ingestImage({ postId, image, near }) {
    const attempts = [];
    const strategies = imageStrategies(image.url);
    for (const strategy of strategies) {
      try {
        const { captures, outcome, queryUrl } = await this.client.capturesFor(strategy.url);
        attempts.push({ method: strategy.method, url: strategy.url, query: queryUrl, outcome, captures: captures.length });
        if (!captures.length) continue;
        const pick = chooseCapture(captures, near);
        const replay = await this.client.fetchCapture(pick.timestamp, strategy.url, { modifier: 'id_' });
        const check = validateImageBody(replay.body, replay.contentType);
        if (!check.ok) {
          attempts[attempts.length - 1].download = { outcome: OUTCOME.BAD_BODY, reason: check.reason, contentType: replay.contentType, bytes: replay.body.length };
          continue;
        }
        const digest = sha256(replay.body);
        const cachePath = join(this.cache, 'images', postId, `${digest}.${check.ext}`);
        if (!existsSync(cachePath)) {
          mkdirSync(dirname(cachePath), { recursive: true });
          appendFileSync(cachePath, replay.body);
        }
        const record = {
          postId,
          originalUrl: image.url,
          resolved: true,
          requestedUrl: strategy.url,
          captureTimestamp: pick.timestamp,
          captureUrl: `https://web.archive.org/web/${pick.timestamp}id_/${strategy.url}`,
          strategy: strategy.method,
          strategyUrl: strategy.url,
          sha256: digest,
          bytes: replay.body.length,
          mimetype: check.mimetype,
          ext: check.ext,
          contentType: replay.contentType,
          caption: image.alt ?? '',
          alt: image.alt ?? '',
          cachePath,
          attempts,
          nearCapture: near,
        };
        this.images.set(`${postId}|${image.url}`, record);
        appendJsonl(PATHS.images, record);
        this.logMethod({ stage: 'crawl-images', postId, url: image.url, outcome: OUTCOME.OK, via: strategy.method, captureTimestamp: pick.timestamp, bytes: replay.body.length, sha256: digest });
        return record;
      } catch (err) {
        const outcome = err.outcome ?? OUTCOME.ERROR;
        attempts.push({ method: strategy.method, url: strategy.url, outcome, error: String(err.message).slice(0, 200) });
        if (outcome === OUTCOME.TIMEOUT || outcome === OUTCOME.THROTTLED || outcome === OUTCOME.TRANSIENT) break;
        if (outcome === OUTCOME.AFTER_CUTOFF) continue;
      }
    }
    const confirmedGap = attempts.every((a) => a.outcome === OUTCOME.ARCHIVE_GAP || a.outcome === OUTCOME.NOT_FOUND);
    const record = {
      postId,
      originalUrl: image.url,
      resolved: false,
      outcome: confirmedGap ? OUTCOME.ARCHIVE_GAP : (attempts.at(-1)?.outcome ?? OUTCOME.ERROR),
      caption: image.alt ?? '',
      attempts,
    };
    this.images.set(`${postId}|${image.url}`, record);
    appendJsonl(PATHS.images, record);
    this.noteMissing({
      kind: 'image',
      postId,
      url: image.url,
      outcome: record.outcome,
      confirmedGap,
      attempts,
    });
    this.logMethod({ stage: 'crawl-images', postId, url: image.url, outcome: record.outcome, attempts: attempts.length });
    return record;
  }

  imageRecordsFor(postId) {
    const post = this.posts.get(postId);
    if (!post) return [];
    return post.images
      .map((image) => this.images.get(`${postId}|${image.url}`))
      .filter(Boolean)
      .filter((record) => record.resolved);
  }

  missingFor(postId) {
    const post = this.posts.get(postId);
    if (!post) return [];
    return post.images
      .map((image) => this.images.get(`${postId}|${image.url}`))
      .filter((record) => record && !record.resolved)
      .map((record) => ({ url: record.originalUrl, outcome: record.outcome, attempts: record.attempts }));
  }

  summary() {
    const posts = [...this.posts.values()];
    const images = [...this.images.values()];
    const published = readJsonl(PATHS.published);
    const missing = readJsonl(PATHS.missing);
    const publishedByPost = new Map();
    for (const record of published) publishedByPost.set(record.postId, record);
    return {
      discoveredCaptureRows: readJsonl(PATHS.postCaptures).length,
      discoveredPosts: this.inventoryPostIds().size,
      parsedPosts: posts.length,
      postsWithContent: posts.filter((p) => (p.captionHtml?.length ?? 0) > 0 || (p.images?.length ?? 0) > 0).length,
      postsWithImages: posts.filter((p) => (p.images?.length ?? 0) > 0).length,
      resolvedImages: images.filter((i) => i.resolved).length,
      missingImages: images.filter((i) => !i.resolved).length,
      missingPosts: missing.filter((m) => m.kind === 'post').length,
      publishedPosts: publishedByPost.size,
      publishedComplete: [...publishedByPost.values()].filter((r) => !r.partial).length,
      publishedPartial: [...publishedByPost.values()].filter((r) => r.partial).length,
      publishedImages: [...publishedByPost.values()].reduce((sum, r) => sum + (r.imageCount ?? 0), 0),
    };
  }
}

export function extractPostHtml(html, parsed) {
  if (parsed?.postHtmlRange) return html.slice(parsed.postHtmlRange[0], parsed.postHtmlRange[1]);
  const start = html.search(/<div[^>]*class=["'][^"']*\bpost\b[^"']*["'][^>]*>/i);
  return start >= 0 ? html.slice(start, start + 40_000) : null;
}

export { stripTags, isoFromTimestamp, readJsonl, CUTOFF, OUTCOME, WaybackClient, appendJsonl };

// Progressive, idempotent OCI publishing to GHCR. One tag per Tumblr post ID.
import { existsSync, readFileSync } from 'node:fs';
import { buildArtifact, GhcrRegistry } from './lib/oci.mjs';
import { PATHS, Recovery } from './pipeline.mjs';
import { appendJsonl, isoFromTimestamp, log, readJsonl, sha256 } from './lib/util.mjs';

export const DEFAULT_REPOSITORY = `${process.env.GHCR_USERNAME ?? 'igor-makarov'}/shurik-hazfalafel-com`;

export function createRegistry({ repository = DEFAULT_REPOSITORY, dryRun = false } = {}) {
  const [registryHost, ...rest] = repository.split('/');
  return new GhcrRegistry({
    registry: registryHost,
    repository: rest.join('/'),
    username: process.env.GHCR_USERNAME,
    token: process.env.GITHUB_TOKEN,
    fetchImpl: dryRun
      ? async () => new Response('{}', { status: 404 })
      : fetch,
  });
}

/**
 * Publish only when the new artifact is at least as complete as what is already
 * published, so reruns can add images/metadata but never regress them.
 */
export function shouldPublish(existing, candidate) {
  if (!existing) return { publish: true, reason: 'new' };
  if (existing.metadataHash === candidate.metadataHash && existing.imageCount === candidate.imageCount) {
    return { publish: false, reason: 'unchanged' };
  }
  const imageRegression = candidate.imageCount < existing.imageCount;
  const textRegression = candidate.captionLength < existing.captionLength;
  const tagRegression = candidate.tagCount < existing.tagCount;
  if (imageRegression || textRegression || tagRegression) {
    return { publish: false, reason: 'would-regress', detail: { candidate, existing } };
  }
  return { publish: true, reason: candidate.imageCount > existing.imageCount ? 'more-images' : 'richer-metadata' };
}

export async function publishPost({ recovery, registry, postId, dryRun = false, createdAt }) {
  const post = recovery.posts.get(postId);
  if (!post) return { postId, outcome: 'unknown-post' };
  const imageRecords = recovery.imageRecordsFor(postId);
  const missing = recovery.missingFor(postId);
  const images = imageRecords.map((record, index) => {
    if (!existsSync(record.cachePath)) return null;
    return {
      data: readFileSync(record.cachePath),
      mimetype: record.mimetype,
      originalUrl: record.originalUrl,
      captureTimestamp: record.captureTimestamp,
      captureUrl: record.captureUrl,
      strategy: record.strategy,
      caption: post.images.find((i) => i.url === record.originalUrl)?.alt ?? record.caption ?? '',
      alt: post.images.find((i) => i.url === record.originalUrl)?.alt ?? record.alt ?? '',
      layerPath: `images/${String(index + 1).padStart(2, '0')}-${record.sha256.slice(0, 8)}.${record.ext}`,
    };
  }).filter(Boolean);

  const artifact = buildArtifact({
    post: {
      ...post,
      expectedImages: post.images?.length ?? 0,
      missingImages: missing.map((m) => ({ url: m.url, outcome: m.outcome })),
      captureUrl: post.captureUrl,
      captures: post.captures ?? [],
    },
    images,
    createdAt: createdAt ?? isoFromTimestamp(post.captureTimestamp) ?? '2020-01-01T00:00:00Z',
  });

  const summary = {
    postId: String(postId),
    imageCount: images.length,
    expectedImageCount: post.images?.length ?? 0,
    captionLength: (post.captionText ?? '').length,
    tagCount: (post.tags ?? []).length,
    metadataHash: sha256(JSON.stringify(artifact.metadata)),
    configDigest: artifact.manifest.config.digest,
    manifestBytes: artifact.manifestBytes.length,
    tag: String(postId),
    partial: images.length < (post.images?.length ?? images.length),
    missingImages: missing.map((m) => ({ url: m.url, outcome: m.outcome })),
    captureTimestamp: post.captureTimestamp,
    publishedAt: new Date().toISOString(),
  };

  const existing = readJsonl(PATHS.published).find((r) => r.postId === String(postId));
  const decision = shouldPublish(existing, summary);
  if (!decision.publish) {
    log(`publish skip ${postId}: ${decision.reason}`);
    return { postId: String(postId), outcome: `skipped:${decision.reason}`, ...summary };
  }
  if (dryRun) {
    log(`publish dry-run ${postId}: ${images.length} layers, tag ${postId}`);
    return { postId: String(postId), outcome: 'dry-run', ...summary };
  }

  await registry.pushBlob(artifact.configBytes);
  for (const layer of artifact.manifest.layers) {
    const matching = artifact.manifest.layers.indexOf(layer);
    void matching;
  }
  for (const image of images) {
    // layer tar bytes are rebuilt identically by buildArtifact; push via digest check
    void image;
  }
  for (const [index, layer] of artifact.manifest.layers.entries()) {
    await registry.pushBlob(layerBytes(artifact, index));
  }
  const result = await registry.pushManifest(String(postId), artifact.manifestBytes);
  const record = { ...summary, outcome: 'published', repository: registry.repository, manifestDigest: result.digest, decision: decision.reason };
  appendJsonl(PATHS.published, record);
  log(`published ${registry.repository}:${postId} layers=${images.length} partial=${record.partial}`);
  return record;
}

/** Rebuild the deterministic tar for a layer index (same inputs => same bytes). */
function layerBytes(artifact, index) {
  const layer = artifact.manifest.layers[index];
  const metadata = artifact.metadata.images[index];
  const caption = [metadata.caption ?? '', metadata.alt ?? ''].filter(Boolean).join('\n');
  // eslint-disable-next-line no-undef
  const { makeTar } = require_makeTar();
  return makeTar([
    { name: metadata.path, data: artifact.layerData[index] },
    { name: `${metadata.path}.caption.txt`, data: `${caption}\n` },
  ]);
}

let cachedMakeTar = null;
function require_makeTar() {
  if (!cachedMakeTar) throw new Error('makeTar not injected');
  return cachedMakeTar;
}

export function configureLayerBuilder(makeTar) {
  cachedMakeTar = makeTar;
}

